/**
 * End-to-end extraction pipeline: MV string in, `{ artists, title }` out.
 *
 * The pipeline is fully deterministic and has no network/LLM dependency:
 * 1. artist names and aliases are matched with the dictionary ({@link module:artists}),
 * 2. title candidates are generated by bracket-aware segmentation
 *    ({@link module:candidates}),
 * 3. candidates are described by features ({@link module:features}),
 * 4. the best candidate is selected by the hand-tuned rule scorer
 *    ({@link module:scoring}) or by a learned ranker ({@link module:model/linear},
 *    {@link module:model/mlp}, {@link module:model/ensemble}).
 *
 * @module extract
 */

import { extractArtists } from './artists.js';
import { buildCandidates } from './candidates.js';
import { FeatureExtractor, FEATURE_NAMES, buildContext } from './features.js';
import { parseBlocks } from './segment.js';
import { ruleScore } from './scoring.js';
import { trimEdgeJunk } from './text.js';

/**
 * A single ranked candidate, exposed for debugging and error analysis.
 *
 * @typedef {object} RankedCandidate
 * @property {string} text Candidate title.
 * @property {number} score Selection score.
 * @property {string} variant Generation variant.
 * @property {number} start Offset in the MV string.
 * @property {string|null} bracket Bracket the candidate was found in, or `null`.
 */

/**
 * Every ranker used by the pipeline exposes this interface.
 *
 * @typedef {object} Ranker
 * @property {string} version Model format version.
 * @property {(vectors: Array<Float64Array|number[]>) => number[]} rank Score a whole candidate pool.
 */

/**
 * Extraction result.
 *
 * @typedef {object} ExtractionResult
 * @property {string[]} artists Canonical artist names in reading order.
 * @property {'dictionary'|'collective'|'guessed'|'empty'} artistSource Which artist rule produced the list.
 * @property {string} title Extracted song title (`''` when nothing plausible was found).
 * @property {RankedCandidate[]} ranked Candidates sorted by score, best first.
 * @property {import('./segment.js').Block[]} blocks Parsed blocks (debugging aid).
 */

/**
 * Run the full extraction on one MV string.
 *
 * @param {string} mv MV title string (e.g. `【洛天依原创】彼方【PV付】`).
 * @param {object} options Extraction options.
 * @param {import('./dictionary.js').EntityDictionary} options.dictionary Artist dictionary.
 * @param {Ranker|null} [options.model=null] Learned ranker; falls back to rule scoring.
 * @param {object} [options.artistOptions] Tuning knobs for {@link module:artists.extractArtists}.
 * @param {number} [options.maxCandidates=96] Candidate pool cap.
 * @returns {ExtractionResult} Artists, title and the ranked candidate list.
 * @example
 * const result = extract('【洛天依】樱花草', { dictionary });
 * // result.artists → ['洛天依']
 * // result.title  → '樱花草'
 */
export function extract(mv, options) {
  if (typeof mv !== 'string') throw new TypeError('extract expects the MV string');
  const { dictionary, model = null } = options;
  if (!dictionary) throw new TypeError('extract requires a dictionary');

  const source = mv.trim();
  if (!source) {
    return { artists: [], artistSource: 'empty', title: '', ranked: [], blocks: [] };
  }

  const blocks = parseBlocks(source);
  const artistInfo = extractArtists(source, dictionary, {
    ...options.artistOptions,
    blocks,
  });
  const { artists, matches } = artistInfo;

  const { candidates } = buildCandidates(source, {
    blocks,
    maxCandidates: options.maxCandidates ?? 96,
  });

  if (candidates.length === 0) {
    return {
      artists,
      artistSource: artistInfo.source,
      title: trimEdgeJunk(source),
      ranked: [],
      blocks,
    };
  }

  const extractor = new FeatureExtractor(buildContext({ mv: source, blocks, artists, matches }));
  const namedFeatures = candidates.map((candidate) => extractor.features(candidate));
  const vectors = namedFeatures.map((named) => extractor.vectorFromNamed(named));
  const scores = model ? model.rank(vectors) : namedFeatures.map((named) => ruleScore(named));

  /** @type {RankedCandidate[]} */
  const ranked = candidates.map((candidate, i) => ({
    text: candidate.text,
    score: scores[i],
    variant: candidate.variant,
    start: candidate.start,
    bracket: blocks[candidate.blockIndex]?.open ?? null,
  }));

  let bestIndex = 0;
  for (let i = 1; i < scores.length; i += 1) {
    if (scores[i] > scores[bestIndex]) bestIndex = i;
  }
  const title = candidates[bestIndex].text.trim();

  ranked.sort((a, b) => b.score - a.score);

  return { artists, artistSource: artistInfo.source, title, ranked, blocks };
}

/**
 * Feature order used by the pipeline (re-exported for training tooling).
 *
 * @returns {readonly string[]} Feature names in model order.
 */
export function featureNames() {
  return FEATURE_NAMES;
}
